const DATE=/^\d{4}-\d{2}-\d{2}$/;
const validDate=value=>DATE.test(value)&&Number.isFinite(Date.parse(value+'T00:00:00Z'))&&new Date(value+'T00:00:00Z').toISOString().slice(0,10)===value;
function csvLine(line){const out=[];let value='',quoted=false,closed=false;for(let i=0;i<line.length;i++){const c=line[i];if(quoted){if(c==='"'&&line[i+1]==='"'){value+='"';i++;}else if(c==='"'){quoted=false;closed=true;}else value+=c;}else if(closed){if(c===','){out.push(value.trim());value='';closed=false;}else if(!/\s/.test(c))throw Error('CSV 闭合引号后存在无效内容。');}else if(c==='"'){if(value)throw Error('CSV 引号位置无效。');quoted=true;}else if(c===','){out.push(value.trim());value='';}else value+=c;}if(quoted)throw Error('CSV 引号未闭合。');out.push(value.trim());return out;}
const key=value=>value.toLowerCase().replace(/[ _-]/g,'');
export function parseDividendCsv(text,{fileName='股息 CSV'}={}){
  if(typeof text!=='string'||!text.trim())throw Error('股息 CSV 为空。');if(new TextEncoder().encode(text).byteLength>5_000_000)throw Error('CSV 超过 5 MB，拒绝导入。');
  const lines=text.replace(/^\uFEFF/,'').split(/\r?\n/).filter(x=>x.trim());if(lines.length<2||lines.length>5001)throw Error('CSV 必须包含表头和 1 至 5,000 条记录。');
  const h=csvLine(lines[0]).map(key),find=names=>h.findIndex(x=>names.includes(x)),ix={ex:find(['exdate','exdividenddate','除息日']),record:find(['recorddate','登记日']),payment:find(['paymentdate','paydate','付款日']),amount:find(['dividend','dividendpershare','pershare','每股股息'])};if(ix.ex<0||ix.amount<0)throw Error('表头必须包含 Ex-Date 和 Dividend（每股金额）；Record Date、Payment Date 可选。');
  const seen=new Set(),rows=[];for(let i=1;i<lines.length;i++){const c=csvLine(lines[i]);if(c.every(x=>!x))continue;const exDate=c[ix.ex],recordDate=ix.record<0?'':c[ix.record],paymentDate=ix.payment<0?'':c[ix.payment],amount=Number((c[ix.amount]||'').replace(/,/g,''));if(!validDate(exDate)||recordDate&&!validDate(recordDate)||paymentDate&&!validDate(paymentDate))throw Error(`第 ${i+1} 行股息日期无效；日期必须是 YYYY-MM-DD。`);if(!Number.isFinite(amount)||amount<=0||amount>1000)throw Error(`第 ${i+1} 行每股股息无效。`);const signature=[exDate,recordDate,paymentDate,amount].join('|');if(seen.has(signature))throw Error(`CSV 重复股息记录：第 ${i+1} 行。`);seen.add(signature);rows.push({id:`div-${i}-${exDate}-${amount}`,exDate,recordDate,paymentDate,perShare:amount,source:'user-dividend-csv',sourceFile:fileName,sourceRow:i+1,dateType:paymentDate?'provided-payment-date-pending-approval':'payment-date-unverified',approved:false});}if(!rows.length)throw Error('CSV 没有有效股息记录。');return rows;
}
export function compareDividendCandidates(existing,incoming){return incoming.map(candidate=>{const matches=existing.filter(event=>{const amount=Math.abs(Number(event.perShare)-candidate.perShare)<=0.0005;const eventDate=event.paymentDate??event.date??event.exDate;const delta=Math.abs(Date.parse(eventDate+'T00:00:00Z')-Date.parse(candidate.exDate+'T00:00:00Z'))/86400000;return amount&&delta<=14;});return{...candidate,suspectedDuplicate:matches.length>0,conflicts:matches.map(x=>({date:x.date??x.exDate??'—',paymentDate:x.paymentDate??null,perShare:x.perShare,source:x.source??'existing'}))};});}
export function approveDividendCandidates(candidates,selectedIds,confirmDuplicates=[]){const selected=new Set(selectedIds),confirmed=new Set(confirmDuplicates),approved=[];for(const x of candidates){if(!selected.has(x.id))continue;if(!validDate(x.paymentDate))throw Error(`股息 ${x.exDate} 缺少经人工确认的 Payment Date；Ex-Date 不会代替付款日。`);if(x.suspectedDuplicate&&!confirmed.has(x.id))throw Error(`股息 ${x.exDate} 疑似重复，须明确确认后才能加入。`);approved.push({date:x.paymentDate,paymentDate:x.paymentDate,exDate:x.exDate,recordDate:x.recordDate||null,perShare:x.perShare,source:'user-dividend-csv-confirmed',sourceFile:x.sourceFile,sourceRow:x.sourceRow,dateType:'confirmed-payment-date',duplicateConfirmed:Boolean(x.suspectedDuplicate)});}return approved;}
